import {remindPage, remindRemove} from "@/api/page/index";
import addedit from "./components/versionRelease/addedit.vue";
import {mapGetters} from "vuex";

export default {
  components: {
    addedit
  },
  data() {
    return {
      loading: false,
      typeList: null,
      queryParams: {
        pageSize: 10,
        currentPage: 1,
        total: 0
      },

      selfCode: '',
      tableData: null,
      editRow: null,
      componentsParams: {
        isShow: false,
        type: null,
      }
    }
  },
  watch: {},
  mounted() {
    //记载默认数据
    this.getList()
    this.initTypes();
  },
  computed: {
    ...mapGetters(["permission", "userInfo"]),
    permissionList() {
      return {
        addBtn: this.vaildData(this.permission.safeaccess_add, false),
        viewBtn: this.vaildData(this.permission.safeaccess_view, false),
        delBtn: this.vaildData(this.permission.safeaccess_delete, false),
        editBtn: this.vaildData(this.permission.safeaccess_edit, false)
      };
    }
  },
  methods: {
    initTypes() {
      this.typeList = [];
      this.typeList.push({
        name: '市',
        id: '2'
      })
      this.typeList.push({
        name: '县',
        id: '3'
      })
    },
    getList() {
      //加载 班组
      this.loading = true
      remindPage({
        ...this.queryParams
      }).then(res => {
        this.tableData = res.data.records
        this.queryParams.total = res.data.total
      }).finally(() => {
        this.loading = false
      })
    },
    handleDelete(id) {
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。", "确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        return remindRemove({ids: id});
      }).then(() => {
        this.getList();
        this.$message({
          type: "success",
          message: "操作成功!"
        });
      });
    },
    handleEdit(row) {
      this.componentsParams.isShow = true;
      this.componentsParams.type = 'edit';
      this.editRow = JSON.parse(JSON.stringify(row));
    },
    handleAdd() {
      this.componentsParams.isShow = true;
      this.componentsParams.type = 'add';
    },
    close() {
      this.componentsParams.isShow = false;
      this.componentsParams.type = null;
      this.editRow = null;
    },
    getTypeName(type) {
      switch (type) {
        case '2':
          return '市';
        case '3':
          return '县';
        default:
          return null;
      }
    }
  }
}
